// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0)); // owner is address(0) initially
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // General rule: a non-owner caller cannot successfully invoke owned().
        assertTrue(!ok, "owned must revert for non-owner");
    }
}
